INSERT INTO crm_wechat_mp_message (
    app_id, open_id, direction, msg_type, content, media_id, pic_url, template_id,
    wx_msg_id, activity_pulse_id, errcode, errmsg, create_time, source
) VALUES (
    #{appId}, #{openId}, #{direction}, #{msgType}, #{content}, #{mediaId}, #{picUrl}, #{templateId},
    #{wxMsgId}, #{activityPulseId}, #{errcode}, #{errmsg}, COALESCE(#{createTime}, now()), #{source}
)
ON CONFLICT (app_id, wx_msg_id) WHERE (wx_msg_id IS NOT NULL) DO NOTHING

